import React from 'react';
import {
  Modal,
  ModalDialog,
  DialogTitle,
  DialogContent,
  Button,
  Box,
  Stack,
} from '@mui/joy';

interface AlertDialogProps {
  open: boolean;
  onClose: () => void;
  title: string;
  content: string;
  onConfirm?: () => void;
  confirmText?: string;
  cancelText?: string;
}

const AlertDialog: React.FC<AlertDialogProps> = ({
  open,
  onClose,
  title,
  content,
  onConfirm,
  confirmText,
  cancelText,
}) => {
  const handleConfirm = () => {
    if (onConfirm) {
      onConfirm();
    }
    onClose(); // Close dialog after confirm
  };

  return (
    <Modal open={open} onClose={onClose}>
      <ModalDialog
        variant="outlined"
        role="alertdialog"
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
      >
        <DialogTitle id="alert-dialog-title">{title}</DialogTitle>
        <DialogContent id="alert-dialog-description">{content}</DialogContent>
        <Box sx={{ display: 'flex', justifyContent: 'flex-end', pt: 2 }}>
          {onConfirm ? (
            <Stack direction="row" spacing={1}>
              <Button variant="plain" color="neutral" onClick={onClose}>
                {cancelText || 'Cancel'}
              </Button>
              <Button variant="solid" color="primary" onClick={handleConfirm}>
                {confirmText || 'Confirm'}
              </Button>
            </Stack>
          ) : (
            <Button onClick={onClose}>{confirmText || 'OK'}</Button>
          )}
        </Box>
      </ModalDialog>
    </Modal>
  );
};

export default AlertDialog;
