import React, { useState, useEffect } from 'react';
import {
  Modal,
  ModalDialog,
  DialogTitle,
  DialogContent,
  Input,
  Button,
  Box,
  FormControl,
  Stack,
  FormLabel,
} from '@mui/joy';
import AlertDialog from './AlertDialog'; // Import AlertDialog

// --- Type Definitions ---
export interface ShipInfoData {
  shipId: string;
  date: string;
  CARRIER_LINE: string;
  VOY: string;
  ETD: string;
  ETA: string;
}

interface EditShipInfoModalProps {
  show: boolean;
  onClose: () => void;
  onSave: (data: Partial<ShipInfoData>) => void;
  onNavigate: () => void;
  onDelete: () => void;
  initialData: ShipInfoData | null;
}

// --- Component ---
const EditShipInfoModal: React.FC<EditShipInfoModalProps> = ({
  show,
  onClose,
  onSave,
  onNavigate,
  onDelete,
  initialData,
}) => {
  const [carrierLine, setCarrierLine] = useState('');
  const [voy, setVoy] = useState('');
  const [etd, setEtd] = useState('');
  const [eta, setEta] = useState('');
  const [error, setError] = useState('');
  const [showConfirmDelete, setShowConfirmDelete] = useState(false); // State for confirmation dialog

  useEffect(() => {
    if (initialData) {
      setCarrierLine(initialData.CARRIER_LINE || '');
      setVoy(initialData.VOY || '');
      setEtd(initialData.ETD || '');
      setEta(initialData.ETA || '');
    }
  }, [initialData]);

  const handleSave = () => {
    if (carrierLine && voy && etd && eta) {
      onSave({
        CARRIER_LINE: carrierLine,
        VOY: voy,
        ETD: etd,
        ETA: eta,
      });
      onClose();
    } else {
      setError('全ての項目を入力してください。');
    }
  };

  const handleDeleteClick = () => {
    setShowConfirmDelete(true);
  };

  const handleConfirmDelete = () => {
    onDelete();
    onClose(); // Close the main modal after deletion
  };

  return (
    <Modal open={show} onClose={onClose}>
      <>
        <ModalDialog sx={{ width: 500 }}>
          <DialogTitle>船舶情報 修正</DialogTitle>
          <DialogContent>
            <Stack spacing={2} sx={{ mt: 2 }}>
              <FormControl>
                <FormLabel>船舶名</FormLabel>
                <Input readOnly value={initialData?.shipId || ''} />
              </FormControl>
              <FormControl>
                <FormLabel>日付</FormLabel>
                <Input readOnly type="date" value={initialData?.date || ''} />
              </FormControl>
              <FormControl>
                <FormLabel>CARRIER LINE</FormLabel>
                <Input
                  value={carrierLine}
                  onChange={(e) => setCarrierLine(e.target.value)}
                />
              </FormControl>
              <FormControl>
                <FormLabel>VSL/VOY NO</FormLabel>
                <Input value={voy} onChange={(e) => setVoy(e.target.value)} />
              </FormControl>
              <FormControl>
                <FormLabel>ETD</FormLabel>
                <Input
                  type="date"
                  value={etd}
                  onChange={(e) => setEtd(e.target.value)}
                />
              </FormControl>
              <FormControl>
                <FormLabel>ETA</FormLabel>
                <Input
                  type="date"
                  value={eta}
                  onChange={(e) => setEta(e.target.value)}
                />
              </FormControl>
              {error && (
                <Box sx={{ color: 'danger.500', fontSize: 'sm', mt: 1 }}>
                  {error}
                </Box>
              )}
            </Stack>
          </DialogContent>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', pt: 2 }}>
            <Button
              variant="solid"
              color="primary"
              onClick={onNavigate}
              sx={{ mr: 'auto' }}
            >
              移動
            </Button>
            <Box sx={{ display: 'flex', gap: 1 }}>
              <Button variant="plain" color="neutral" onClick={onClose}>
                戻る
              </Button>
              <Button
                variant="solid"
                color="danger"
                onClick={handleDeleteClick}
              >
                削除
              </Button>
              <Button variant="solid" color="primary" onClick={handleSave}>
                保存
              </Button>
            </Box>
          </Box>
        </ModalDialog>

        {/* Confirmation Dialog for Deletion */}
        <AlertDialog
          open={showConfirmDelete}
          onClose={() => setShowConfirmDelete(false)}
          title="削除の確認"
          content="本当にこの船の情報を削除しますか？"
          onConfirm={handleConfirmDelete}
          confirmText="削除"
          cancelText="キャンセル"
        />
      </>
    </Modal>
  );
};

export default EditShipInfoModal;
