import React, { useState } from 'react';
import styled from 'styled-components';

const ModalBackdrop = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
`;

const ModalContent = styled.div`
  background: white;
  padding: 20px;
  border-radius: 8px;
  width: 400px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  & > h2 {
    margin-bottom: 20px;
    align-self: flex-start;
  }
`;

const Input = styled.input`
  width: 100%;
  padding: 8px;
  margin-bottom: 10px;
  border-radius: 4px;
  border: 1px solid #ccc;
`;

const ButtonContainer = styled.div`
  display: flex;
  justify-content: flex-end;
  align-self: flex-end;
  margin-top: 20px;
`;

const Button = styled.button`
  padding: 10px 20px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  margin-left: 10px;

  &.save {
    background-color: #4caf50;
    color: white;
  }

  &.cancel {
    background-color: #f44336;
    color: white;
  }
`;

export interface RegisterUserData {
  email: string;
  name: string;
  company: string;
  role: 'master-admin' | 'admin' | 'operator' | 'viewer';
}

interface Props {
  show: boolean;
  onClose: () => void;
  onSave: (data: any) => void;
}

const RegisterUserModal: React.FC<Props> = ({ show, onClose, onSave }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [company, setCompany] = useState('');

  const handleSave = () => {
    onSave({ email, password, name, company });
  };

  if (!show) {
    return null;
  }

  return (
    <ModalBackdrop>
      <ModalContent>
        <h2>유저 등록</h2>
        <Input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <Input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <Input
          type="text"
          placeholder="Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <Input
          type="text"
          placeholder="Company"
          value={company}
          onChange={(e) => setCompany(e.target.value)}
        />
        <ButtonContainer>
          <Button className="cancel" onClick={onClose}>
            취소
          </Button>
          <Button className="save" onClick={handleSave}>
            등록
          </Button>
        </ButtonContainer>
      </ModalContent>
    </ModalBackdrop>
  );
};

export default RegisterUserModal;
