import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Calendar as BigCalendar,
  momentLocalizer,
  ToolbarProps,
} from 'react-big-calendar';
import moment from 'moment';
import 'moment/locale/ja';
import 'react-big-calendar/lib/css/react-big-calendar.css';
import styled from 'styled-components';
import {
  collection,
  getDocs,
  query,
  where,
  doc,
  setDoc,
  updateDoc,
  getDoc,
  arrayUnion,
  arrayRemove,
  deleteDoc,
} from 'firebase/firestore';
import { db } from '../utils/firebase';
import AddShipModal, { ShipData } from '../components/AddEventModal';
import EditShipInfoModal, {
  ShipInfoData,
} from '../components/EditShipInfoModal';
import AlertDialog from '../components/AlertDialog'; // Import AlertDialog
import { AppUser } from '../App'; // Import AppUser type

// --- Type Definitions ---
interface MyEvent {
  title: string;
  start: Date;
  end: Date;
  allDay?: boolean;
  shipId: string; // Unique identifier for the ship
  date: string; // Date in 'YYYY-MM-DD' format
}

interface MyCalendarProps {
  user: AppUser | null; // Prop to receive user info
}

// --- Styled Components ---
const CalendarWrapper = styled.div`
  width: 100%;
  height: 90%; /* Adjust height to fill remaining space */
  padding: 20px;
  box-sizing: border-box;
`;

const CalendarContainer = styled.div`
  position: relative;
  z-index: 1;
  height: 90%;
`;

const StyledToolbar = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
  font-family: Arial, sans-serif;

  .rbc-btn-group button {
    color: #37352f;
    background: white;
    border: 1px solid #ddd;
    border-radius: 4px;
    padding: 5px 12px;
    cursor: pointer;
    margin: 0 2px;

    &:hover {
      background: #f5f5f5;
    }

    &:disabled {
      background: #f0f0f0;
      color: #aaa;
      cursor: not-allowed;
    }
  }

  .rbc-toolbar-label {
    font-size: 1.4em;
    font-weight: bold;
  }
`;

moment.locale('ja'); // Set locale to Japanese
const localizer = momentLocalizer(moment);

// --- Main Component ---
const MyCalendar: React.FC<MyCalendarProps> = ({ user }) => {
  const [date, setDate] = useState(new Date());
  const [events, setEvents] = useState<MyEvent[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [selectedShip, setSelectedShip] = useState<ShipInfoData | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false); // State for general AlertDialog
  const [dialogInfo, setDialogInfo] = useState({ title: '', content: '' }); // State for general AlertDialog content
  const navigate = useNavigate();

  const fetchEvents = useCallback(async (startDate: Date, endDate: Date) => {
    const start = moment(startDate).format('YYYY-MM-DD');
    const end = moment(endDate).format('YYYY-MM-DD');

    try {
      const q = query(
        collection(db, 'daily_ships'),
        where('__name__', '>=', start),
        where('__name__', '<=', end)
      );
      const querySnapshot = await getDocs(q);
      const newEvents: MyEvent[] = [];
      querySnapshot.forEach((doc) => {
        const data = doc.data();
        const docId = doc.id;
        const eventDate = moment(docId, 'YYYY-MM-DD').toDate();

        if (data.shipIdentifiers && Array.isArray(data.shipIdentifiers)) {
          data.shipIdentifiers.forEach((shipId: string) => {
            newEvents.push({
              title: shipId, // Display shipId on the calendar
              shipId: shipId,
              start: eventDate,
              end: eventDate,
              allDay: true,
              date: docId,
            });
          });
        }
      });
      setEvents(newEvents);
    } catch (error) {
      console.error('Error fetching events: ', error);
      setDialogInfo({
        title: 'エラー',
        content: 'イベントの取得に失敗しました。',
      });
      setDialogOpen(true);
    }
  }, []);

  useEffect(() => {
    const startOfMonth = moment(date).startOf('month').toDate();
    const endOfMonth = moment(date).endOf('month').toDate();
    fetchEvents(startOfMonth, endOfMonth);
  }, [date, fetchEvents]);

  const handleNavigate = (newDate: Date) => {
    setDate(newDate);
  };

  const handleSelectEvent = async (event: MyEvent) => {
    if (user?.role === 'viewer') {
      navigate(`/detail/${event.date}/${event.shipId}`);
    } else {
      try {
        const shipDocRef = doc(
          db,
          `daily_ships/${event.date}/ships/${event.shipId}`
        );
        const shipDocSnap = await getDoc(shipDocRef);

        if (shipDocSnap.exists()) {
          const shipData = shipDocSnap.data();
          setSelectedShip({
            shipId: event.shipId,
            date: event.date,
            CARRIER_LINE: shipData.CARRIER_LINE,
            VOY: shipData.VOY,
            ETD: shipData.ETD,
            ETA: shipData.ETA,
          });
          setShowEditModal(true);
        } else {
          console.error('No such ship document!');
          setDialogInfo({
            title: 'エラー',
            content: '該当する船の情報が見つかりません。',
          });
          setDialogOpen(true);
          // Fallback navigation if ship not found
          navigate(`/detail/${event.date}/${event.shipId}`);
        }
      } catch (error) {
        console.error('Error fetching ship details: ', error);
        setDialogInfo({
          title: 'エラー',
          content: '船の詳細情報の取得に失敗しました。',
        });
        setDialogOpen(true);
        // Fallback navigation on error
        navigate(`/detail/${event.date}/${event.shipId}`);
      }
    }
  };

  const handleSaveShip = async (data: ShipData) => {
    const { title, date, carrierLine, voy, etd, eta } = data;
    const dailyShipDocRef = doc(db, 'daily_ships', date);
    const shipDocRef = doc(dailyShipDocRef, 'ships', title);

    try {
      const dailyShipDocSnap = await getDoc(dailyShipDocRef);
      if (dailyShipDocSnap.exists()) {
        await updateDoc(dailyShipDocRef, {
          shipIdentifiers: arrayUnion(title),
        });
      } else {
        await setDoc(dailyShipDocRef, { shipIdentifiers: [title] });
      }

      const shipDataForDb = {
        CARRIER_LINE: carrierLine,
        VOY: voy,
        ETD: etd,
        ETA: eta,
      };
      await setDoc(shipDocRef, shipDataForDb, { merge: true });

      const startOfMonth = moment(date).startOf('month').toDate();
      const endOfMonth = moment(date).endOf('month').toDate();
      fetchEvents(startOfMonth, endOfMonth);
      setShowAddModal(false);
      setDialogInfo({ title: '成功', content: '船が正常に追加されました。' });
      setDialogOpen(true);
    } catch (error) {
      console.error('Error saving ship:', error);
      setDialogInfo({ title: 'エラー', content: '船の追加に失敗しました。' });
      setDialogOpen(true);
    }
  };

  const handleUpdateShip = async (data: Partial<ShipInfoData>) => {
    if (!selectedShip) return;

    const shipDocRef = doc(
      db,
      `daily_ships/${selectedShip.date}/ships/${selectedShip.shipId}`
    );

    try {
      await updateDoc(shipDocRef, data);
      setShowEditModal(false);
      setDialogInfo({ title: '成功', content: '船の情報が更新されました。' });
      setDialogOpen(true);
    } catch (error) {
      console.error('Error updating ship:', error);
      setDialogInfo({
        title: 'エラー',
        content: '船の情報の更新に失敗しました。',
      });
      setDialogOpen(true);
    }
  };

  const handleDeleteShip = async () => {
    if (!selectedShip) return;

    const { date, shipId } = selectedShip;
    const dailyShipDocRef = doc(db, 'daily_ships', date);
    const shipDocRef = doc(dailyShipDocRef, 'ships', shipId);

    try {
      await deleteDoc(shipDocRef);
      await updateDoc(dailyShipDocRef, {
        shipIdentifiers: arrayRemove(shipId),
      });

      setShowEditModal(false);
      const startOfMonth = moment(date).startOf('month').toDate();
      const endOfMonth = moment(date).endOf('month').toDate();
      fetchEvents(startOfMonth, endOfMonth);

      setDialogInfo({ title: '成功', content: '船の情報を削除しました。' });
      setDialogOpen(true);
    } catch (error) {
      console.error('Error deleting ship:', error);
      setDialogInfo({
        title: 'エラー',
        content: '船の情報の削除に失敗しました。',
      });
      setDialogOpen(true);
    }
  };

  const CustomToolbar = (toolbar: ToolbarProps<MyEvent>) => {
    const canAddShip =
      user?.role === 'admin' ||
      user?.role === 'operator' ||
      user?.role === 'master-admin';

    return (
      <StyledToolbar>
        <span className="rbc-btn-group">
          <button type="button" onClick={() => toolbar.onNavigate('TODAY')}>
            今日
          </button>
          <button type="button" onClick={() => toolbar.onNavigate('PREV')}>
            {'<'}
          </button>
          <button type="button" onClick={() => toolbar.onNavigate('NEXT')}>
            {' >'}
          </button>
        </span>
        <span className="rbc-toolbar-label">
          {moment(toolbar.date).format('YYYY年 MM月')}
        </span>
        <span className="rbc-btn-group">
          <button
            type="button"
            onClick={() => setShowAddModal(true)}
            disabled={!canAddShip}
          >
            +
          </button>
        </span>
      </StyledToolbar>
    );
  };

  return (
    <CalendarWrapper>
      <h3>TYO/YOK – PUSAN : ETD MON , WED , FRI / 週３回</h3>
      <h3>TYO/YOK – INCHEON : ETD FRI / 週１回</h3>
      <CalendarContainer>
        <BigCalendar<MyEvent>
          localizer={localizer}
          events={events}
          startAccessor="start"
          endAccessor="end"
          style={{ height: '100%' }}
          date={date}
          onNavigate={handleNavigate}
          onSelectEvent={handleSelectEvent}
          views={['month']}
          components={{ toolbar: CustomToolbar }}
        />
      </CalendarContainer>
      <AddShipModal
        show={showAddModal}
        onClose={() => setShowAddModal(false)}
        onSave={handleSaveShip}
      />
      {selectedShip && (
        <EditShipInfoModal
          show={showEditModal}
          onClose={() => setShowEditModal(false)}
          onSave={handleUpdateShip}
          onDelete={handleDeleteShip}
          initialData={selectedShip}
          onNavigate={() => {
            navigate(`/detail/${selectedShip.date}/${selectedShip.shipId}`);
            setShowEditModal(false);
          }}
        />
      )}
      {/* General AlertDialog for messages */}
      <AlertDialog
        open={dialogOpen}
        onClose={() => setDialogOpen(false)}
        title={dialogInfo.title}
        content={dialogInfo.content}
      />
    </CalendarWrapper>
  );
};

export default MyCalendar;
