import React, { useState, useEffect, useCallback } from 'react';
import { AgGridReact } from 'ag-grid-react';
import {
  ColDef,
  CellValueChangedEvent,
  ICellRendererParams,
} from 'ag-grid-community';
import 'ag-grid-community/styles/ag-grid.css';
import 'ag-grid-community/styles/ag-theme-alpine.css'; // Change theme
import {
  collection,
  getDocs,
  doc,
  writeBatch,
  setDoc,
} from 'firebase/firestore';
import { getAuth, createUserWithEmailAndPassword } from 'firebase/auth';
import { getFunctions, httpsCallable } from 'firebase/functions';
import { db } from '../utils/firebase';
import styled from 'styled-components';
import RegisterUserModal from '../components/RegisterUserModal';
import AlertDialog from '../components/AlertDialog';

// --- Styled Components ---
const PageContainer = styled.div`
  display: flex;
  flex-direction: column;
  height: 75vh;
  padding: 20px;
  box-sizing: border-box;
`;

const GridContainer = styled.div`
  width: 100%;
  flex-grow: 1;
`;

const ButtonContainer = styled.div`
  display: flex;
  justify-content: flex-end;
  margin-top: 20px;
  gap: 10px;
`;

const Button = styled.button`
  border: none;
  color: white;
  padding: 12px 28px;
  text-align: center;
  text-decoration: none;
  display: inline-block;
  font-size: 16px;
  cursor: pointer;
  border-radius: 8px;
  transition: background-color 0.3s;

  &:hover {
    opacity: 0.9;
  }
`;

const SaveButton = styled(Button)`
  background-color: #4caf50; // Green
`;

const RegisterButton = styled(Button)`
  background-color: #008cba; // Blue
`;

const DeleteButton = styled.button`
  background-color: #f44336;
  color: white;
  border: none;
  padding: 5px 10px;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.3s;

  &:hover {
    opacity: 0.9;
  }
`;

// --- Types ---
interface UserData {
  id: string;
  name: string;
  company: string;
  email: string;
  role: 'master-admin' | 'admin' | 'operator' | 'viewer';
}

// --- Main Component ---
const MasterAdmin = () => {
  // --- State ---
  const [rowData, setRowData] = useState<UserData[]>([]);
  const [modifiedRows, setModifiedRows] = useState<Record<string, UserData>>(
    {}
  );
  const [showRegisterModal, setShowRegisterModal] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [dialogInfo, setDialogInfo] = useState({ title: '', content: '' });
  const [showConfirmDeleteUser, setShowConfirmDeleteUser] = useState(false);
  const [userToDeleteUid, setUserToDeleteUid] = useState<string | null>(null);

  const fetchUsers = useCallback(async () => {
    const usersCollection = collection(db, 'users');
    const userSnapshot = await getDocs(usersCollection);
    const userList = userSnapshot.docs.map(
      (doc) => ({ id: doc.id, ...doc.data() } as UserData)
    );
    setRowData(userList);
  }, []);

  useEffect(() => {
    fetchUsers();
  }, [fetchUsers]);

  const handleDeleteUser = async (uid: string) => {
    setUserToDeleteUid(uid);
    setShowConfirmDeleteUser(true);
  };

  const handleConfirmDeleteUser = async () => {
    if (!userToDeleteUid) return;

    try {
      const functions = getFunctions();
      const deleteUser = httpsCallable(functions, 'deleteUser');
      await deleteUser({ uid: userToDeleteUid });
      fetchUsers();
      setDialogInfo({ title: '成功', content: '유저 정보를 삭제했습니다.' });
      setDialogOpen(true);
    } catch (error) {
      console.error('Error deleting user: ', error);
      setDialogInfo({ title: 'エラー', content: '삭제에 실패했습니다. 다시 시도해주세요.' });
      setDialogOpen(true);
    } finally {
      setUserToDeleteUid(null);
      setShowConfirmDeleteUser(false);
    }
  };

  const [colDefs] = useState<ColDef[]>([
    {
      headerName: 'No.',
      valueGetter: 'node.rowIndex + 1',
      width: 80,
      editable: false,
      sortable: true,
      filter: false,
    },
    {
      headerName: '유저명',
      field: 'name',
      editable: true,
      flex: 1,
      minWidth: 150,
      filter: false,
    },
    {
      headerName: '회사명',
      field: 'company',
      editable: true,
      flex: 1,
      minWidth: 150,
      filter: false,
    },
    {
      headerName: '이메일',
      field: 'email',
      editable: false,
      flex: 2,
      minWidth: 200,
      filter: false,
    },
    {
      headerName: '권한',
      field: 'role',
      editable: true,
      cellEditor: 'agSelectCellEditor',
      cellEditorParams: {
        values: ['master-admin', 'admin', 'operator', 'viewer'],
      },
      width: 150,
      filter: false,
    },
    {
      headerName: 'Actions',
      cellRenderer: (params: ICellRendererParams) => (
        <DeleteButton onClick={() => handleDeleteUser(params.data.id)}>
          삭제
        </DeleteButton>
      ),
      editable: false,
      width: 100,
      sortable: false,
      filter: false,
    },
  ]);

  const onCellValueChanged = useCallback(
    (event: CellValueChangedEvent<UserData>) => {
      const { data } = event;
      setModifiedRows((prev) => ({ ...prev, [data.id]: data }));
    },
    []
  );

  const handleSaveChanges = async () => {
    if (Object.keys(modifiedRows).length === 0) {
      setDialogInfo({ title: '情報', content: '수정 사항이 없습니다.' });
      setDialogOpen(true);
      return;
    }

    try {
      const batch = writeBatch(db);
      for (const id in modifiedRows) {
        const userRef = doc(db, 'users', id);
        const { id: userId, ...dataToUpdate } = modifiedRows[id];
        batch.update(userRef, dataToUpdate);
      }
      await batch.commit();
      setModifiedRows({});
      setDialogInfo({ title: '成功', content: '수정 사항이 저장되었습니다.' });
      setDialogOpen(true);
    } catch (error) {
      console.error('Error saving changes: ', error);
      setDialogInfo({ title: 'エラー', content: '저장에 실패했습니다. 다시 시도해주세요.' });
      setDialogOpen(true);
    }
  };

  const handleRegisterUser = async (data: any) => {
    const auth = getAuth();
    try {
      const userCredential = await createUserWithEmailAndPassword(
        auth,
        data.email,
        data.password
      );
      const newUser = userCredential.user;

      await setDoc(doc(db, 'users', newUser.uid), {
        name: data.name,
        company: data.company,
        email: data.email,
        role: 'viewer', // Default role
      });

      setShowRegisterModal(false);
      fetchUsers(); // Refresh the user list
      setDialogInfo({ title: '成功', content: '유저가 성공적으로 등록되었습니다.' });
      setDialogOpen(true);
    } catch (error) {
      console.error('Error registering user: ', error);
      setDialogInfo({ title: 'エラー', content: '등록에 실패했습니다. 다시 시도해주세요.' });
      setDialogOpen(true);
    }
  };

  // --- Render ---
  return (
    <PageContainer>
      <h1>유저 관리</h1>
      <GridContainer className="ag-theme-alpine-dark">
        <AgGridReact<UserData>
          rowData={rowData}
          columnDefs={colDefs}
          defaultColDef={{
            sortable: true,
            filter: true,
            resizable: true,
          }}
          onCellValueChanged={onCellValueChanged}
          rowSelection="multiple"
          suppressRowClickSelection={true}
          localeText={{ noRowsToShow: 'データが存在しません。' }}
        />
      </GridContainer>
      <ButtonContainer>
        <RegisterButton onClick={() => setShowRegisterModal(true)}>
          유저 등록
        </RegisterButton>
        <SaveButton onClick={handleSaveChanges}>저장</SaveButton>
      </ButtonContainer>
      <RegisterUserModal
        show={showRegisterModal}
        onClose={() => setShowRegisterModal(false)}
        onSave={handleRegisterUser}
      />
      <AlertDialog
        open={dialogOpen}
        onClose={() => setDialogOpen(false)}
        title={dialogInfo.title}
        content={dialogInfo.content}
      />
      {/* Confirmation Dialog for User Deletion */}
      <AlertDialog
        open={showConfirmDeleteUser}
        onClose={() => setShowConfirmDeleteUser(false)}
        title="削除の確認"
        content="本当にこのユーザーを削除しますか？"
        onConfirm={handleConfirmDeleteUser}
        confirmText="削除"
        cancelText="キャンセル"
      />
    </PageContainer>
  );
};

export default MasterAdmin;